export interface MasterBank {
  id: string;
  code: string;
  name: string;
  short_name: string;
  slug: string;
  official_website: string;
  official_domain: string;
  logo: string;
  color: string;
  established_year: number;
  active: boolean;
}

export interface MasterRate {
  id: string;
  bank_id: string;
  currency: string;
  channel: "online" | "counter";
  term_value: number;
  term_unit: "day" | "month" | "year";
  interest_rate: number;
  payment_method: "maturity" | "monthly" | "quarterly" | "upfront";
  min_amount: number;
  max_amount?: number;
  customer_segment: string;
  note?: string;
  source_url: string;
  verified_at: string;
}

