export function getBankVerifiedUrl(bankId: string, fallbackWebsite?: string): string {
  if (BANK_VERIFIED_DEPOSIT_URLS[bankId]) {
    return BANK_VERIFIED_DEPOSIT_URLS[bankId];
  }
  return fallbackWebsite || "https://sbv.gov.vn";
}

